const handleAuthenticate = (): void => {
  if (!otpDisplay) { return; }
  analytics.track(ACTION_EVENTS.LOGIN_ATTEMPTED);
  dispatch(authenticateStart({ mobileNumber: mobileRef.current, otp: otpRef.current, userType: selectedUserType }));
};

const handleGetOtp = (): void => {
  if (mobileDisplay.length !== 10) { return; }
  analytics.track(ACTION_EVENTS.OTP_ATTEMPTED);
  dispatch(requestOtpStart({ mobileNumber: mobileRef.current, userType: selectedUserType }));
};

return {
  success: true,
  message: `OTP sent to ${request.mobileNumber}`,
};
